   // src/services/parser/documentParser.ts
   import fs from 'fs-extra';
   import path from 'path';
   import matter from 'gray-matter';
   import { marked } from 'marked';
   import { ParsedDocument, DocumentMetadata, DocumentSection } from '../../models/document';

   export async function parseDocument(filePath: string): Promise<ParsedDocument> {
     const content = await fs.readFile(filePath, 'utf-8');
     const { data, content: markdownContent } = matter(content);

     const metadata: DocumentMetadata = {
       ...data,
       path: filePath,
       filename: path.basename(filePath)
     };

     const sections = parseDocumentSections(markdownContent);

     return {
       metadata,
       content: markdownContent,
       sections
     };
   }

   function parseDocumentSections(content: string): DocumentSection[] {
     const tokens = marked.lexer(content);
     const sections: DocumentSection[] = [];
     let currentSection: DocumentSection | null = null;
     let currentLevel = 0;

     for (const token of tokens) {
       if (token.type === 'heading') {
         const newSection: DocumentSection = {
           title: token.text,
           level: token.depth,
           content: '',
           subsections: []
         };

         if (!currentSection || token.depth <= currentLevel) {
           sections.push(newSection);
           currentSection = newSection;
           currentLevel = token.depth;
         } else {
           currentSection.subsections.push(newSection);
         }
       } else if (token.type === 'paragraph' || token.type === 'code' || token.type === 'list') {
         if (currentSection) {
           currentSection.content += marked.parser([token as marked.Token]);
         }
       }
     }

     return sections;
   }
   ```

