   ```typescript
   // src/services/analyzer/typeDetector.ts
   import { ParsedDocument } from '../../models/document';

   const TYPE_KEYWORDS = {
     'system-guide': ['system', 'guide', 'architecture', 'overview', 'design'],
     'troubleshooting': ['troubleshoot', 'issue', 'problem', 'error', 'debug', 'fix'],
     'setup': ['setup', 'installation', 'configure', 'install', 'getting started']
   };

   export function determineDocumentType(document: ParsedDocument): string {
     // First check metadata
     if (document.metadata.category) {
       return document.metadata.category.toLowerCase();
     }

     // Check document title
     const title = document.metadata.title || document.sections[0]?.title || '';
     for (const [type, keywords] of Object.entries(TYPE_KEYWORDS)) {
       if (keywords.some(keyword => title.toLowerCase().includes(keyword))) {
         return type;
       }
     }

     // Check content
     const contentText = document.content.toLowerCase();
     const typeScores = Object.entries(TYPE_KEYWORDS).map(([type, keywords]) => {
       const score = keywords.reduce((sum, keyword) => {
         const regex = new RegExp(keyword, 'gi');
         const matches = contentText.match(regex);
         return sum + (matches ? matches.length : 0);
       }, 0);
       return { type, score };
     });

     typeScores.sort((a, b) => b.score - a.score);
     return typeScores[0].score > 0 ? typeScores[0].type : 'general';
   }
   ```

