   // src/services/analyzer/informationExtractor.ts
   import { ParsedDocument, DocumentSection } from '../../models/document';
   import { KeyInformation } from './documentAnalyzer';

   const IMPORTANCE_INDICATORS = [
     'important', 'critical', 'key', 'note', 'warning', 'caution',
     'remember', 'essential', 'crucial', 'vital'
   ];

   export function extractKeyInformation(document: ParsedDocument): KeyInformation[] {
     const keyInfo: KeyInformation[] = [];

     // Process each section
     function processSection(section: DocumentSection, parentTitle: string = '') {
       const sectionPath = parentTitle ? `${parentTitle} > ${section.title}` : section.title;

       // Check if section contains key information
       const importance = calculateImportance(section);
       if (importance > 0) {
         keyInfo.push({
           content: section.content,
           section: sectionPath,
           importance,
           sourcePath: document.metadata.path
         });
       }

       // Process subsections
       for (const subsection of section.subsections) {
         processSection(subsection, sectionPath);
       }
     }

     for (const section of document.sections) {
       processSection(section);
     }

     return keyInfo;
   }

   function calculateImportance(section: DocumentSection): number {
     let importance = 0;

     // Higher importance for sections with key indicators
     for (const indicator of IMPORTANCE_INDICATORS) {
       if (section.title.toLowerCase().includes(indicator)) {
         importance += 2;
       }
       if (section.content.toLowerCase().includes(indicator)) {
         importance += 1;
       }
     }

     // Higher importance for code blocks
     if (section.content.includes('```')) {
       importance += 2;
     }

     // Higher importance for lists
     if ((section.content.match(/^\s*[-*]\s/gm) || []).length > 0) {
       importance += 1;
     }

     return importance;
   }
   ```

