   // src/services/analyzer/duplicateDetector.ts
   import { ParsedDocument } from '../../models/document';

   export function detectDuplicates(documents: ParsedDocument[]): Map<string, string> {
     const duplicates = new Map<string, string>();
     const contentHashes = new Map<string, string>();

     for (const document of documents) {
       // Create a simple hash of the document content
       const contentHash = hashContent(document.content);

       if (contentHashes.has(contentHash)) {
         // This is a duplicate
         duplicates.set(document.metadata.path, contentHashes.get(contentHash)!);
       } else {
         contentHashes.set(contentHash, document.metadata.path);
       }
     }

     return duplicates;
   }

   function hashContent(content: string): string {
     // Simple hash function for content comparison
     // In a real implementation, use a more robust algorithm
     return content
       .replace(/\s+/g, ' ')
       .trim()
       .toLowerCase()
       .slice(0, 100);
   }
