   import { ParsedDocument } from '../../models/document';
   import { analyzeDocument, AnalysisResult } from './documentAnalyzer';
   import { detectDuplicates } from './duplicateDetector';

   export interface AnalyzedCollection {
     documentsByType: Map<string, ParsedDocument[]>;
     analysisResults: Map<string, AnalysisResult>;
     duplicates: Map<string, string>;
   }

   export function analyzeDocumentCollection(documents: ParsedDocument[]): AnalyzedCollection {
     const documentsByType = new Map<string, ParsedDocument[]>();
     const analysisResults = new Map<string, AnalysisResult>();

     // Analyze each document
     for (const document of documents) {
       const analysis = analyzeDocument(document);
       analysisResults.set(document.metadata.path, analysis);

       // Group by type
       if (!documentsByType.has(analysis.documentType)) {
         documentsByType.set(analysis.documentType, []);
       }
       documentsByType.get(analysis.documentType)!.push(document);
     }

     // Detect duplicates
     const duplicates = detectDuplicates(documents);

     return {
       documentsByType,
       analysisResults,
       duplicates
     };
   }
