   ```typescript
   // src/services/generator/footnoteGenerator.ts
   import { Footnote, FootnoteReference } from '../../models/footnote';
   import { KeyInformation } from '../analyzer/documentAnalyzer';
   import { ParsedDocument } from '../../models/document';
   import path from 'path';

   export class FootnoteManager {
     private footnotes: Footnote[] = [];
     private footnoteMap = new Map<string, number>();

     constructor(private format: string = 'numbered', private style: string = '[1], [2], [3]') {}

     public addFootnote(document: ParsedDocument, section?: string, content?: string): number {
       const sourceKey = `${document.metadata.path}:${section || ''}`;

       // Check if this footnote already exists
       if (this.footnoteMap.has(sourceKey)) {
         return this.footnoteMap.get(sourceKey)!;
       }

       // Create new footnote
       const id = this.footnotes.length + 1;
       const footnote: Footnote = {
         id,
         sourcePath: document.metadata.path,
         sourceTitle: document.metadata.title || path.basename(document.metadata.path),
         content: content || '',
         section
       };

       this.footnotes.push(footnote);
       this.footnoteMap.set(sourceKey, id);

       return id;
     }

     public addFootnoteForKeyInfo(keyInfo: KeyInformation): number {
       const sourceKey = `${keyInfo.sourcePath}:${keyInfo.section}`;

       if (this.footnoteMap.has(sourceKey)) {
         return this.footnoteMap.get(sourceKey)!;
       }

       const id = this.footnotes.length + 1;
       const footnote: Footnote = {
         id,
         sourcePath: keyInfo.sourcePath,
         sourceTitle: path.basename(keyInfo.sourcePath),
         content: keyInfo.content,
         section: keyInfo.section
       };

       this.footnotes.push(footnote);
       this.footnoteMap.set(sourceKey, id);

       return id;
     }

     public getFootnoteMarker(id: number): string {
       if (this.style === '[1], [2], [3]') {
         return `[${id}]`;
       }
       return `(${id})`; // Alternative style
     }

     public getAllFootnotes(): Footnote[] {
       return [...this.footnotes];
     }

     public generateReferencesSection(): string {
       let referencesSection = '## References\n\n';

       for (const footnote of this.footnotes) {
         const marker = this.getFootnoteMarker(footnote.id);
         const relativePath = footnote.sourcePath.replace(/\\/g, '/');
         referencesSection += `${marker} **${footnote.sourceTitle}** - \`${relativePath}\``;  

         if (footnote.section) {
           referencesSection += ` (Section: ${footnote.section})`;
         }

         referencesSection += '\n\n';
       }

       return referencesSection;
     }
   }
   ```

