   // src/services/generator/contentWithFootnotes.ts
   import { FootnoteManager } from './footnoteGenerator';
   import { KeyInformation } from '../analyzer/documentAnalyzer';

   export function generateContentWithFootnotes(
     keyInformation: KeyInformation[],
     footnoteManager: FootnoteManager
   ): string {
     // Sort key information by importance
     keyInformation.sort((a, b) => b.importance - a.importance);

     let content = '';
     const processedSections = new Set<string>();

     for (const info of keyInformation) {
       // Skip duplicate sections
       if (processedSections.has(info.section)) {
         continue;
       }

       processedSections.add(info.section);

       // Add section header if not already present
       if (!content.includes(`## ${info.section}`)) {
         content += `## ${info.section}\n\n`;
       }

       // Add content with footnote
       const footnoteId = footnoteManager.addFootnoteForKeyInfo(info);
       const footnoteMarker = footnoteManager.getFootnoteMarker(footnoteId);

       content += `${info.content} ${footnoteMarker}\n\n`;
     }

     // Add references section
     content += footnoteManager.generateReferencesSection();

     return content;
   }
