   // src/services/generator/documentGenerator.ts
   import fs from 'fs-extra';
   import path from 'path';
   import { ParsedDocument } from '../../models/document';
   import { KeyInformation } from '../analyzer/documentAnalyzer';
   import { FootnoteManager } from './footnoteGenerator';
   import { generateContentWithFootnotes } from './contentWithFootnotes';
   import { getTemplate, applyTemplate, TemplateData } from './templateManager';
   import { GenerationOptions, GenerationResult } from '../../models/generator';
   import { getConfig } from '../../config';

   export async function generateRootDocument(
     documentType: string,
     documents: ParsedDocument[],
     keyInformation: KeyInformation[],
     targetDir: string,
     options: GenerationOptions
   ): Promise<GenerationResult> {
     const config = getConfig();
     const targetFileName = config.targets[documentType] || `${documentType.toUpperCase()}.md`;
     const targetPath = path.join(targetDir, targetFileName);

     // Create footnote manager
     const footnoteManager = new FootnoteManager(
       config.footnoting.format,
       config.footnoting.style
     );

     // Filter key information for this document type
     const relevantInfo = keyInformation.filter(info => {
       const sourcePath = info.sourcePath;
       const sourceDoc = documents.find(doc => doc.metadata.path === sourcePath);
       return sourceDoc && sourceDoc.metadata.category === documentType;
     });

     // Generate content with footnotes
     const content = generateContentWithFootnotes(relevantInfo, footnoteManager);

     // Apply template
     const template = getTemplate(documentType);
     const templateData: TemplateData = {
       title: `${documentType.charAt(0).toUpperCase() + documentType.slice(1)} Documentation`,
       description: `Consolidated ${documentType} documentation.`,
       content,
       generatedDate: new Date().toISOString().split('T')[0],
       sourceCount: documents.length
     };

     const outputContent = applyTemplate(template, templateData);

     // If dry run, don't write file
     if (options.dryRun) {
       console.log(`Would write to ${targetPath}:\n${outputContent.slice(0, 200)}...`);
       return {
         targetPath,
         documentType,
         footnoteCount: footnoteManager.getAllFootnotes().length,
         sourceCount: documents.length,
         success: true
       };
     }

     // Check if file exists and handle accordingly
     if (await fs.pathExists(targetPath) && options.preserveExisting) {
       // Merge with existing content
       const existingContent = await fs.readFile(targetPath, 'utf-8');
       // TODO: Implement smart merging logic
       await fs.writeFile(targetPath, outputContent);
     } else {
       // Write new file
       await fs.writeFile(targetPath, outputContent);
     }

     return {
       targetPath,
       documentType,
       footnoteCount: footnoteManager.getAllFootnotes().length,
       sourceCount: documents.length,
       success: true
     };
   }
