   // src/services/generator/contentMerger.ts
   import { marked } from 'marked';

   export function mergeContent(existing: string, generated: string): string {
     // Parse both documents
     const existingTokens = marked.lexer(existing);
     const generatedTokens = marked.lexer(generated);

     // Extract sections from both
     const existingSections = extractSections(existingTokens);
     const generatedSections = extractSections(generatedTokens);

     // Merge sections
     const mergedSections = new Map<string, string>();

     // First add all existing sections
     for (const [title, content] of existingSections.entries()) {
       mergedSections.set(title, content);
     }

     // Then add or update with generated sections
     for (const [title, content] of generatedSections.entries()) {
       if (mergedSections.has(title)) {
         // Append new content to existing section
         const existingContent = mergedSections.get(title)!;
         mergedSections.set(title, existingContent + '\n\n' + content);
       } else {
         mergedSections.set(title, content);
       }
     }

     // Rebuild document
     let result = '';

     // Add title and description from generated content
     const titleMatch = generated.match(/^# (.+)$/m);
     if (titleMatch) {
       result += `# ${titleMatch[1]}\n\n`;
     }

     const descMatch = generated.match(/^> (.+)$/m);
     if (descMatch) {
       result += `> ${descMatch[1]}\n> Generated on ${new Date().toISOString().split('T')[0]}.\n\n`;
     }

     // Add all sections
     for (const [title, content] of mergedSections.entries()) {
       if (title === 'root') continue; // Skip root content
       result += `## ${title}\n\n${content}\n\n`;
     }

     // Add references section from generated content
     const referencesMatch = generated.match(/## References\n\n([\s\S]+)$/m);
     if (referencesMatch) {
       result += `## References\n\n${referencesMatch[1]}`;
     }

     return result;
   }

   function extractSections(tokens: marked.TokensList): Map<string, string> {
     const sections = new Map<string, string>();
     let currentSection = 'root';
     let currentContent = '';

     for (const token of tokens) {
       if (token.type === 'heading' && token.depth === 2) {
         // Save previous section
         if (currentContent.trim()) {
           sections.set(currentSection, currentContent.trim());
         }

         // Start new section
         currentSection = token.text;
         currentContent = '';
       } else {
         // Add to current section
         currentContent += marked.parser([token as marked.Token]) + '\n';
       }
     }

     // Save last section
     if (currentContent.trim()) {
       sections.set(currentSection, currentContent.trim());
     }

     return sections;
   }
