   // src/services/monitor/fileWatcher.ts
   import chokidar from 'chokidar';
   import path from 'path';
   import { consolidate } from '../consolidation';

   export class DocumentationWatcher {
     private watcher: chokidar.FSWatcher | null = null;
     private debounceTimeout: NodeJS.Timeout | null = null;
     private readonly debounceTime = 5000; // 5 seconds

     constructor(
       private sources: string[],
       private targetDir: string,
       private types: string[] = []
     ) {}

     public start(): void {
       const patterns = this.sources.map(source => path.join(source, '**/*.{md,txt}'));

       this.watcher = chokidar.watch(patterns, {
         persistent: true,
         ignoreInitial: true,
         awaitWriteFinish: {
           stabilityThreshold: 2000,
           pollInterval: 100
         }
       });

       this.watcher
         .on('add', this.handleChange.bind(this))
         .on('change', this.handleChange.bind(this))
         .on('unlink', this.handleChange.bind(this));

       console.log(`Watching for changes in: ${this.sources.join(', ')}`);
     }

     public stop(): void {
       if (this.watcher) {
         this.watcher.close();
         this.watcher = null;
       }

       if (this.debounceTimeout) {
         clearTimeout(this.debounceTimeout);
         this.debounceTimeout = null;
       }

       console.log('Stopped watching for changes.');
     }

     private handleChange(filePath: string): void {
       console.log(`Change detected: ${filePath}`);

       // Debounce to avoid multiple consolidations
       if (this.debounceTimeout) {
         clearTimeout(this.debounceTimeout);
       }

       this.debounceTimeout = setTimeout(async () => {
         console.log('Consolidating after changes...');

         try {
           await consolidate({
             sources: this.sources,
             targetDir: this.targetDir,
             types: this.types,
             dryRun: false
           });
         } catch (error) {
           console.error('Error during auto-consolidation:', error);
         }
       }, this.debounceTime);
     }
   }
